1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #14161c;
16	    color: #e8e8ec;
17	    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
18	  }
19	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
20	  .board {
21	    display: grid;
22	    grid-template-columns: repeat(10, 28px);
23	    grid-template-rows: repeat(20, 28px);
24	    gap: 1px;
25	    padding: 1px;
26	    background: #2a2d36;
27	    border: 2px solid #3a3e4a;
28	  }
29	  .cell { width: 28px; height: 28px; background: #0d0e12; }
30	  .side { display: flex; flex-direction: column; gap: 16px; min-width: 140px; }
31	  .panel { background: #1d2028; border: 1px solid #2f333d; padding: 10px 12px; }
32	  .label { font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; color: #8a8f9c; }
33	  .value { font-size: 22px; font-weight: 600; margin-top: 2px; }
34	  .preview {
35	    display: grid;
36	    grid-template-columns: repeat(4, 16px);
37	    grid-template-rows: repeat(2, 16px);
38	    gap: 1px;
39	    margin-top: 8px;
40	  }
41	  .preview .mini { width: 16px; height: 16px; background: transparent; }
42	  .status { font-size: 14px; color: #ff8a8a; min-height: 18px; }
43	  button {
44	    font: inherit;
45	    background: #2f333d;
46	    color: #e8e8ec;
47	    border: 1px solid #454a57;
48	    padding: 6px 10px;
49	    cursor: pointer;
50	  }
51	  button:hover { background: #3a3e4a; }
52	  .help { font-size: 12px; color: #8a8f9c; line-height: 1.6; }
53	
54	  /* Piece colours, shared by the board and the preview. */
55	  [data-piece="I"] { background: #22c5e6 !important; }
56	  [data-piece="O"] { background: #f2d024 !important; }
57	  [data-piece="T"] { background: #a64ee6 !important; }
58	  [data-piece="S"] { background: #3fcf5a !important; }
59	  [data-piece="Z"] { background: #e8423f !important; }
60	  [data-piece="J"] { background: #3563e9 !important; }
61	  [data-piece="L"] { background: #f08a24 !important; }
62	</style>
63	</head>
64	<body>
65	<div class="game">
66	  <div class="board" data-testid="board" id="board"></div>
67	  <div class="side">
68	    <div class="panel"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
69	    <div class="panel"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
70	    <div class="panel"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
71	    <div class="panel"><div class="label">Next</div><div class="preview" id="preview"></div></div>
72	    <div class="status" id="status"></div>
73	    <button type="button" id="restart">New game</button>
74	    <div class="help">← → move<br>↓ soft drop<br>Space hard drop</div>
75	  </div>
76	</div>
77	<script>
78	(function () {
79	  "use strict";
80	
81	  var ROWS = 20;
82	  var COLS = 10;
83	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
84	  var MIN_UPCOMING = 5;
85	
86	  // Spawn shapes as [row, col] offsets from the top-left of the spawn box.
87	  var SHAPES = {
88	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
89	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
90	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
91	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
92	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
93	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
94	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
95	  };
96	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
97	  var LINE_SCORES = [0, 100, 300, 500, 800];
98	
99	  // board[row][col] is a piece letter or null. The renderer and getBoard both read it.
100	  var board;
101	  var current;   // { type, row, col } or null
102	  var upcoming;  // array of piece letters, soonest first
103	  var score, level, lines, status;
104	  var timer = null;
105	
106	  var boardEl = document.getElementById("board");
107	  var previewEl = document.getElementById("preview");
108	  var scoreEl = document.getElementById("score");
109	  var levelEl = document.getElementById("level");
110	  var linesEl = document.getElementById("lines");
111	  var statusEl = document.getElementById("status");
112	  var cellEls = [];
113	  var previewEls = [];
114	
115	  // [REQ-001] Build the 200 board cells and the preview cells once.
116	  function buildDom() {
117	    for (var r = 0; r < ROWS; r++) {
118	      cellEls.push([]);
119	      for (var c = 0; c < COLS; c++) {
120	        var el = document.createElement("div");
121	        el.className = "cell";
122	        el.setAttribute("data-testid", "cell");
123	        el.setAttribute("data-row", String(r));
124	        el.setAttribute("data-col", String(c));
125	        el.setAttribute("data-filled", "false");
126	        el.setAttribute("data-piece", "");
127	        boardEl.appendChild(el);
128	        cellEls[r].push(el);
129	      }
130	    }
131	    for (var i = 0; i < 8; i++) {
132	      var m = document.createElement("div");
133	      m.className = "mini";
134	      m.setAttribute("data-piece", "");
135	      previewEl.appendChild(m);
136	      previewEls.push(m);
137	    }
138	  }
139	
140	  function emptyBoard() {
141	    var b = [];
142	    for (var r = 0; r < ROWS; r++) {
143	      var row = [];
144	      for (var c = 0; c < COLS; c++) row.push(null);
145	      b.push(row);
146	    }
147	    return b;
148	  }
149	
150	  function isType(t) { return TYPES.indexOf(t) !== -1; }
151	
152	  // [REQ-001] Random generator: a shuffled bag of all seven pieces.
153	  function randomBag() {
154	    var bag = TYPES.slice();
155	    for (var i = bag.length - 1; i > 0; i--) {
156	      var j = Math.floor(Math.random() * (i + 1));
157	      var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
158	    }
159	    return bag;
160	  }
161	
162	  function fillUpcoming() {
163	    while (upcoming.length < MIN_UPCOMING) upcoming = upcoming.concat(randomBag());
164	  }
165	
166	  function cellsOf(piece, row, col) {
167	    return SHAPES[piece.type].map(function (o) { return [row + o[0], col + o[1]]; });
168	  }
169	
170	  function fits(piece, row, col) {
171	    var cells = cellsOf(piece, row, col);
172	    for (var i = 0; i < cells.length; i++) {
173	      var r = cells[i][0], c = cells[i][1];
174	      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
175	      if (board[r][c]) return false;
176	    }
177	    return true;
178	  }
179	
180	  // [REQ-001] Take the next piece from the queue and place it at the top.
181	  function spawn() {
182	    fillUpcoming();
183	    var type = upcoming.shift();
184	    fillUpcoming();
185	    var piece = { type: type, row: 0, col: SPAWN_COL[type] };
186	    if (!fits(piece, piece.row, piece.col)) {
187	      current = null;
188	      status = "over";
189	      stopTimer();
190	      return;
191	    }
192	    current = piece;
193	  }
194	
195	  function clearLines() {
196	    var kept = board.filter(function (row) {
197	      return row.some(function (v) { return !v; });
198	    });
199	    var cleared = ROWS - kept.length;
200	    while (kept.length < ROWS) {
201	      var empty = [];
202	      for (var c = 0; c < COLS; c++) empty.push(null);
203	      kept.unshift(empty);
204	    }
205	    board = kept;
206	    if (cleared > 0) {
207	      score += LINE_SCORES[cleared] * level;
208	      lines += cleared;
209	      var newLevel = Math.floor(lines / 10) + 1;
210	      if (newLevel !== level) {
211	        level = newLevel;
212	        if (status === "running") startTimer();
213	      }
214	    }
215	  }
216	
217	  // [REQ-001] Lock the falling piece into the board, clear lines, spawn the next piece.
218	  function lockPiece() {
219	    cellsOf(current, current.row, current.col).forEach(function (rc) {
220	      board[rc[0]][rc[1]] = current.type;
221	    });
222	    current = null;
223	    clearLines();
224	    spawn();
225	  }
226	
227	  // [REQ-001] One gravity step. The real timer and __tetris.tick both call this.
228	  function gravityStep() {
229	    if (status !== "running" || !current) return;
230	    if (fits(current, current.row + 1, current.col)) {
231	      current.row += 1;
232	    } else {
233	      lockPiece();
234	    }
235	  }
236	
237	  // [REQ-001] Player actions: left, right, softDrop, hardDrop.
238	  function doInput(action) {
239	    if (status !== "running" || !current) return;
240	    if (action === "left") {
241	      if (fits(current, current.row, current.col - 1)) current.col -= 1;
242	    } else if (action === "right") {
243	      if (fits(current, current.row, current.col + 1)) current.col += 1;
244	    } else if (action === "softDrop") {
245	      if (fits(current, current.row + 1, current.col)) current.row += 1;
246	    } else if (action === "hardDrop") {
247	      while (fits(current, current.row + 1, current.col)) current.row += 1;
248	      lockPiece();
249	    }
250	  }
251	
252	  function gravityInterval() {
253	    return Math.max(100, 1000 - (level - 1) * 90);
254	  }
255	
256	  function stopTimer() {
257	    if (timer !== null) { clearInterval(timer); timer = null; }
258	  }
259	
260	  function startTimer() {
261	    stopTimer();
262	    timer = setInterval(function () {
263	      gravityStep();
264	      render();
265	    }, gravityInterval());
266	  }
267	
268	  // [REQ-001] Draw the whole game state into the DOM, synchronously.
269	  function render() {
270	    var drawn = board.map(function (row) { return row.slice(); });
271	    if (current) {
272	      cellsOf(current, current.row, current.col).forEach(function (rc) {
273	        drawn[rc[0]][rc[1]] = current.type;
274	      });
275	    }
276	    for (var r = 0; r < ROWS; r++) {
277	      for (var c = 0; c < COLS; c++) {
278	        var v = drawn[r][c] || "";
279	        var el = cellEls[r][c];
280	        if (el.getAttribute("data-piece") !== v) {
281	          el.setAttribute("data-piece", v);
282	          el.setAttribute("data-filled", v ? "true" : "false");
283	        }
284	      }
285	    }
286	    previewEls.forEach(function (m) { m.setAttribute("data-piece", ""); });
287	    var nextType = upcoming[0];
288	    if (nextType) {
289	      SHAPES[nextType].forEach(function (o) {
290	        previewEls[o[0] * 4 + o[1]].setAttribute("data-piece", nextType);
291	      });
292	    }
293	    scoreEl.textContent = String(score);
294	    levelEl.textContent = String(level);
295	    linesEl.textContent = String(lines);
296	    statusEl.textContent = status === "over" ? "Game over" : "";
297	  }
298	
299	  // [REQ-001] Start a fresh game, optionally from a fixed piece queue.
300	  function newGame(queue) {
301	    board = emptyBoard();
302	    score = 0;
303	    level = 1;
304	    lines = 0;
305	    status = "running";
306	    upcoming = Array.isArray(queue) ? queue.filter(isType) : [];
307	    current = null;
308	    spawn();
309	    if (status === "running") startTimer();
310	    render();
311	  }
312	
313	  window.__tetris = {
314	    newGame: function (queue) { newGame(queue); },
315	
316	    setQueue: function (queue) {
317	      upcoming = Array.isArray(queue) ? queue.filter(isType) : [];
318	      fillUpcoming();
319	      render();
320	    },
321	
322	    setBoard: function (rows) {
323	      var b = emptyBoard();
324	      for (var r = 0; r < ROWS; r++) {
325	        var line = (rows && rows[r]) || "";
326	        for (var c = 0; c < COLS; c++) {
327	          var ch = line.charAt(c);
328	          b[r][c] = isType(ch) ? ch : null;
329	        }
330	      }
331	      board = b;
332	      render();
333	    },
334	
335	    tick: function (n) {
336	      if (n === undefined) n = 1;
337	      for (var i = 0; i < n; i++) gravityStep();
338	      if (status === "running") startTimer();
339	      render();
340	    },
341	
342	    input: function (action) {
343	      doInput(action);
344	      render();
345	    },
346	
347	    getBoard: function () {
348	      return board.map(function (row) {
349	        return row.map(function (v) { return v || "."; }).join("");
350	      });
351	    },
352	
353	    getState: function () {
354	      return {
355	        current: current
356	          ? { type: current.type, cells: cellsOf(current, current.row, current.col) }
357	          : null,
358	        next: upcoming.slice(),
359	        score: score,
360	        level: level,
361	        lines: lines,
362	        status: status
363	      };
364	    }
365	  };
366	
367	  var KEYS = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", " ": "hardDrop" };
368	
369	  document.addEventListener("keydown", function (e) {
370	    var action = KEYS[e.key];
371	    if (!action) return;
372	    e.preventDefault();
373	    window.__tetris.input(action);
374	  });
375	
376	  document.getElementById("restart").addEventListener("click", function (e) {
377	    e.currentTarget.blur();
378	    newGame();
379	  });
380	
381	  buildDom();
382	  newGame();
383	})();
384	</script>
385	</body>
386	</html>
387

