python3 - <<'EOF'
p='index.html'; s=open(p).read()
def rep(a,b):
    global s
    assert s.count(a)==1, a
    s=s.replace(a,b)
rep('''  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };''','''  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
  // Size of the square box each piece rotates inside.
  var BOX = { I: 4, O: 2, T: 3, S: 3, Z: 3, J: 3, L: 3 };
  // Sideways shifts tried, in order, when a rotated shape does not fit in place.
  var KICKS = [0, -1, 1, -2, 2];
  // Locking rule (decision): 2 ticks unable to fall, left/right restarts it at most 3 times.
  var LOCK_TICKS = 2;
  var MAX_LOCK_RESETS = 3;''')
rep('''  var current;   // { type, row, col } or null''','''  var current;   // { type, cells, row, col, lockTicks, lockResets } or null''')
rep('''    return SHAPES[piece.type].map(function (o) { return [row + o[0], col + o[1]]; });''','''    return piece.cells.map(function (o) { return [row + o[0], col + o[1]]; });''')
rep('''    var piece = { type: type, row: 0, col: SPAWN_COL[type] };''','''    var piece = {
      type: type,
      cells: SHAPES[type].map(function (o) { return o.slice(); }),
      row: 0,
      col: SPAWN_COL[type],
      lockTicks: 0,
      lockResets: 0
    };''')
rep('''  // [REQ-001] One gravity step. The real timer and __tetris.tick both call this.
  function gravityStep() {
    if (status !== "running" || !current) return;
    if (fits(current, current.row + 1, current.col)) {
      current.row += 1;
    } else {
      lockPiece();
    }
  }''','''  // [REQ-001] One gravity step. The real timer and __tetris.tick both call this.
  // [REQ-002] A step that cannot move the piece down counts one tick of lock delay.
  function gravityStep() {
    if (status !== "running" || !current) return;
    if (fits(current, current.row + 1, current.col)) {
      current.row += 1;
      current.lockTicks = 0;
    } else {
      current.lockTicks += 1;
      if (current.lockTicks >= LOCK_TICKS) lockPiece();
    }
  }

  // [REQ-002] Sideways move. While resting, a move restarts the lock delay, at most 3 times per piece.
  function shift(dx) {
    if (!fits(current, current.row, current.col + dx)) return;
    var resting = !fits(current, current.row + 1, current.col);
    current.col += dx;
    if (resting && current.lockResets < MAX_LOCK_RESETS) {
      current.lockResets += 1;
      current.lockTicks = 0;
    }
  }

  // [REQ-002] Rotate clockwise inside the piece's box; try sideways shifts; refuse if none fit.
  function rotateCW() {
    var n = BOX[current.type];
    var rotated = { type: current.type, cells: current.cells.map(function (o) { return [o[1], n - 1 - o[0]]; }) };
    for (var i = 0; i < KICKS.length; i++) {
      if (fits(rotated, current.row, current.col + KICKS[i])) {
        current.cells = rotated.cells;
        current.col += KICKS[i];
        return;
      }
    }
  }''')
rep('''  // [REQ-001] Player actions: left, right, softDrop, hardDrop.
  function doInput(action) {
    if (status !== "running" || !current) return;
    if (action === "left") {
      if (fits(current, current.row, current.col - 1)) current.col -= 1;
    } else if (action === "right") {
      if (fits(current, current.row, current.col + 1)) current.col += 1;
    } else if''','''  // [REQ-001] Player actions: left, right, softDrop, hardDrop. [REQ-002] rotateCW.
  function doInput(action) {
    if (status !== "running" || !current) return;
    if (action === "left") {
      shift(-1);
    } else if (action === "right") {
      shift(1);
    } else if (action === "rotateCW") {
      rotateCW();
    } else if''')
rep('''<div class="help">← → move<br>''','''<div class="help">← → move<br>↑ rotate<br>''')
rep('''ArrowDown: "softDrop", " ": "hardDrop" };''','''ArrowDown: "softDrop", ArrowUp: "rotateCW", " ": "hardDrop" };''')
open(p,'w').write(s)
EOF
